function monitorDetectionMarkup(item,monitor){
 if(!item)return '<div class="ipdns-probe-result"><strong>多点探测：尚未配置</strong><p>配置探测来源后，此处每 5 秒刷新已有结果。</p></div>';
 const run=item.run,details=run?.details||[],pending=run&&['creating','pending','queued','issued'].includes(run.status),failed=details.some(x=>x.state==='unreachable'),unknown=details.some(x=>x.state==='unknown');
 const tone=pending?'pending':!details.length||unknown?'unknown':failed?'failed':'reachable';
 const label=item.source_kind==='boce'?'BOCE 国内探测':'自建探针';
 const headline=pending?'检测中，等待节点结果':!details.length||unknown?(run?.status||item.status||'等待检测'):details.every(x=>x.state==='reachable')?'国内可达':details.every(x=>x.state==='unreachable')?'国内不通（疑似被墙）':'部分线路不通';
 const stamp=run?.updated||item.checked;const date=stamp?new Date(stamp*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'尚未检测';
 return `<div class="ipdns-probe-result probe-${tone}"><strong>${label}：${esc(headline)}</strong>${['reboot','change_api'].includes(item.response_mode)?`<button type="button" role="switch" aria-checked="${item.action_enabled!==false}" data-action-toggle="${item.server_id}" data-action-enabled="${item.action_enabled!==false}" class="ipdns-action-switch">${item.response_mode==='reboot'?'自动重启换 IP':'自动换 IP API'}：${item.action_enabled===false?'已暂停 · 点击开启':'已开启 · 点击暂停'}</button>`:'<small>自动换 IP：未配置动作</small>'}<p>${esc(item.source_name)} · ${item.monitor_enabled===false?'监控已暂停':item.source_enabled?(item.automatic?'定时探测已开启':'仅手动探测'):'来源已暂停'}<br>结果更新：${date}${run?`<br>检测目标：${esc(run.ip)}:${run.port}`:''}${run&&(item.current_ip||monitor?.current_ip)&&(run.ip!==(item.current_ip||monitor?.current_ip)||run.port!==(item.current_port||monitor?.port||run.port))?'<br><b>此结果针对旧 IP 或端口，请等待新目标的探测结果。</b>':''}</p><div class="ipdns-probe-nodes">${details.map(x=>`<span class="probe-node-${['reachable','unreachable','unknown'].includes(x.state)?x.state:'unknown'}">${esc(x.name||x.node_id)}：${({reachable:'可达',unreachable:'不通',unknown:'未知'})[x.state]||'未知'}${Number.isFinite(x.latency_ms)?' '+x.latency_ms+' ms':''}</span>`).join('')}</div>${item.failure_streak?`<p>连续完整失败：${item.failure_streak} / ${item.failure_threshold}</p>`:''}${item.recovery?`<p><strong>换 IP 恢复进度</strong><br>当前恢复任务尝试次数：${item.recovery.action_attempts||0}<br>${esc(item.recovery.action_result||'等待处理')}</p>`:run?.action_result?`<p>自动处理：${esc(run.action_result)}</p>`:''}<small>结果每 5 秒刷新；实际探测按设定间隔执行，TCP 不通不等于已确认被墙。</small></div>`;
}
