function monitorMarkup(d){
 const active=d.monitors.filter(m=>m.enabled).length,changed=d.monitors.filter(m=>m.previous_ip).length;
 return `<div class="ipdns-summary"><div><small>已选 VPS</small><strong>${d.monitors.length}</strong></div><div><small>监控运行中</small><strong>${active}</strong></div><div><small>记录到 IP 变化</small><strong>${changed}</strong></div><div><small>自动解析绑定</small><strong>${d.bindings.filter(b=>b.automatic&&d.monitors.some(m=>m.server_id===b.server_id&&m.enabled)).length}</strong></div></div><div class="ipdns-heading"><div><h3>被监控的 VPS</h3><p>先选 VPS，再配置解析。检测来自面板服务器，不能据此直接判断国内被墙。</p></div><button id="selectMonitoredVPS" class="primary">＋ 选择 VPS 加入监控</button></div><div class="ipdns-nodes">${d.monitors.map(m=>`<div class="ipdns-node"><div class="ipdns-heading"><strong>${esc(m.name)}</strong><span>${m.enabled?'监控中':'已暂停'}</span></div><small>当前公网 IPv4</small><div class="ipdns-address">${esc(m.current_ip||'等待上报')}</div><p>上一个 IP：${esc(m.previous_ip||'尚无变化记录')}<br>TCP 端口：${m.port}<br>${esc(m.status)}<br>${m.checked?esc(new Date(m.checked*1000).toLocaleString()):'尚未检测'}</p><div data-monitor-detection="${m.server_id}" aria-live="polite">${monitorDetectionMarkup((d.detections||[]).find(x=>x.server_id===m.server_id),m)}</div><div class="detail-actions"><button data-monitor-check="${m.server_id}">控制端 TCP 检测</button><button data-monitor-config="${m.server_id}">配置</button><button data-monitor-bind="${m.server_id}">绑定解析</button><button data-monitor-history="${m.server_id}">换 IP 记录</button><button data-monitor-remove="${m.server_id}">移出监控</button></div></div>`).join('')||'<p class="ipdns-empty">尚未选择 VPS。点击上方按钮，从已有服务器中勾选。</p>'}</div><hr>`;
}
function bindMonitorButtons(d){
 $('selectMonitoredVPS').onclick=()=>{
  const available=d.servers.filter(s=>!d.monitors.some(m=>m.server_id===s.id));
  modal(`<h2>选择被监控的 VPS</h2><p>仅加入所选服务器，不重启、不修改 DNS。已加入的 VPS 不会重复添加。</p><form id="monitorSelection"><div class="ipdns-selection">${available.map(s=>`<label><input type="checkbox" name="server" value="${s.id}"> ${esc(s.name)} <small>#${s.id}</small></label>`).join('')||'<p>现有 VPS 已全部加入监控。请先在服务器页面添加新 VPS。</p>'}</div><label>首次检测 TCP 端口<input name="port" type="number" min="1" max="65535" value="443" required></label><button class="primary" ${available.length?'':'disabled'}>加入选中的 VPS</button><p id="monitorSelectionError" role="status"></p></form>`);
  $('monitorSelection').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const form=new FormData(e.target);await api('ip-dns/monitors','POST',{server_ids:form.getAll('server').map(Number),port:Number(form.get('port'))});$('modal').close();await loadIPDNS();}catch(e){$('monitorSelectionError').textContent=e.message;}finally{e.submitter.disabled=false;}};
 };
 document.querySelectorAll('[data-monitor-check]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await api('ip-dns/monitors/'+b.dataset.monitorCheck+'/check','POST',{});notice(r.status);}catch(e){notice(e.message);}finally{await loadIPDNS();}});
 document.querySelectorAll('[data-monitor-bind]').forEach(b=>b.onclick=()=>editDNSBinding({server_id:Number(b.dataset.monitorBind),source_id:d.monitors.find(m=>m.server_id===Number(b.dataset.monitorBind))?.source_id}));
 document.querySelectorAll('[data-monitor-config]').forEach(b=>b.onclick=()=>{
  const m=d.monitors.find(x=>x.server_id===Number(b.dataset.monitorConfig));
  modal(`<h2>${esc(m.name)} · 监控配置</h2><form id="monitorConfig"><label>IP 来源<select name="source_id"><option value="">本机 agent（CMHK）</option>${dnsOptions(d.connections.filter(c=>c.kind==='provider'),m.source_id)}</select></label><label>业务 TCP 端口<input name="port" type="number" min="1" max="65535" value="${m.port}" required></label><label><input name="enabled" type="checkbox" ${m.enabled?'checked':''}> 启用监控及该 VPS 的自动解析任务</label><p>暂停后保留绑定与历史，后台不再自动检测或同步此 VPS。手动同步按钮仍可用。</p><button class="primary">保存配置</button><p id="monitorConfigError" role="status"></p></form>`);
  $('monitorConfig').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await api('ip-dns/monitors/'+m.server_id,'PATCH',{port:Number(e.target.elements.port.value),enabled:e.target.elements.enabled.checked,source_id:Number(e.target.elements.source_id.value)||null});$('modal').close();await loadIPDNS();}catch(e){$('monitorConfigError').textContent=e.message;}finally{e.submitter.disabled=false;}};
 });
 document.querySelectorAll('[data-monitor-history]').forEach(b=>b.onclick=async()=>{try{servers=await api('servers');await showIPHistory(Number(b.dataset.monitorHistory));}catch(e){notice(e.message);}});
 document.querySelectorAll('[data-monitor-remove]').forEach(b=>b.onclick=async()=>{if(!confirm('移出监控会保留服务器和解析绑定；需先关闭此 VPS 的自动同步。继续？'))return;try{await api('ip-dns/monitors/'+b.dataset.monitorRemove,'DELETE');await loadIPDNS();}catch(e){notice(e.message);}});
}

function rotationLiveMarkup(r){
 const phase=r.failover_leases?.length?'A 故障转移接替中':{active:r.mode==='fixed_primary'?(r.active_server_id===r.primary_server_id?'主机服务中，等待切入':'轮换机接替中，等待切回'):'等待轮换',draining:'旧机连接排空',waiting_ip:'等待新 IP',waiting_probe:'新 IP 探测中'}[r.phase]||r.phase;
 const left=Math.max(0,Math.ceil(r.next_switch_at-Date.now()/1000));
 const clock=[Math.floor(left/3600),Math.floor(left%3600/60),left%60].map(x=>String(x).padStart(2,'0')).join(':');
 const countdown=r.failover_leases?.length?'故障接替期间暂停定时轮换':!r.enabled?'已暂停':r.phase!=='active'?'恢复流程中；完成后继续轮换':left?clock:'已到计划时间，等待切换条件满足';
 return `<p><strong>轮换状态：${r.enabled?esc(phase):'定时轮换已暂停，故障切换保留'}</strong> · 当前承载 ${esc(r.active_name)}<br>下次 DNS 切换：${esc(new Date(r.next_switch_at*1000).toLocaleString())}<br><strong>轮换倒计时：${countdown}</strong><br>${esc(r.status||'等待执行')}</p>`;
}
function rotationHistoryMarkup(r){return `<h4>最近轮换记录</h4>${(r.events||[]).map(e=>`<div class="audit-row">${esc(e.message)}<small>${esc(new Date(e.created*1000).toLocaleString())} · VPS #${e.server_id}</small></div>`).join('')||'<p>暂无轮换记录；首次执行后显示。</p>'}`;}
let adminRotationLiveTimer=null;
function startAdminRotationLive(data){
 clearInterval(adminRotationLiveTimer);let rows=data.rotations,ticks=0,busy=false;
 adminRotationLiveTimer=setInterval(async()=>{
  if(!$('modal').open||!$('newAdminRotation')){clearInterval(adminRotationLiveTimer);return;}
  for(const r of rows){const el=$('rotationLive-'+r.id);if(el)el.innerHTML=rotationLiveMarkup(r);}
  if(++ticks%5||busy)return;busy=true;
  try{const fresh=await api('admin/rotations');if(!$('newAdminRotation'))return;rows=fresh.rotations;for(const r of rows){const el=$('rotationHistory-'+r.id);if(el)el.innerHTML=rotationHistoryMarkup(r);}if($('adminRotationLiveError'))$('adminRotationLiveError').textContent='';}
  catch(e){if($('adminRotationLiveError'))$('adminRotationLiveError').textContent='状态更新失败：'+e.message;}
  finally{busy=false;}
 },1000);
}
function adminRotationsMarkup(data){
 return `<h2>后台双 VPS 轮换</h2><p>使用后台探测计划、换 IP API 和 DNS 绑定创建轮换；已有客户计划也可在此管理，凭证仍按原计划隔离。</p><button type="button" id="newAdminRotation" class="primary">＋ 创建双 VPS 轮换</button>${data.rotations.map(r=>`<section class="ip-history-panel"><h3>${esc(r.primary_name)} ⇄ ${esc(r.other_name)}</h3><p>${r.mode==='fixed_primary'?'固定主机＋移动线路轮换 · B 承载 '+r.interval_s/60+' 分钟':'双机交替轮换（原模式）'}</p><p>${r.owner_role==='admin'?'后台计划':'客户计划'} · ${r.enabled?'已开启':'已暂停'} · 当前承载 ${esc(r.active_name)}<br>周期 ${r.interval_s/60} 分钟 / 提前 ${(r.lead_s||0)/60} 分钟 / 无心跳 ${r.offline_after_s} 秒<br>${esc(r.status)}${r.failover_name?'<br>A 故障转移 VPS：'+esc(r.failover_name)+' · '+esc(r.failover_status||'待命'):''}</p><div id="rotationLive-${r.id}">${rotationLiveMarkup(r)}</div><details><summary>查看轮换记录</summary><div id="rotationHistory-${r.id}">${rotationHistoryMarkup(r)}</div></details><div class="detail-actions"><button type="button" data-rotation-edit="${r.id}">配置 / 预检</button><button type="button" data-rotation-toggle="${r.id}">${r.enabled?'暂停定时轮换':'开启定时轮换'}</button><button type="button" data-rotation-delete="${r.id}">删除</button></div></section>`).join('')||'<p>尚无轮换任务，点击上方按钮创建。</p>'}<p id="adminRotationLiveError" role="status"></p><p id="adminRotationMessage" role="status"></p>`;
}
async function loadAdminRotations(){
 try{const data=await api('admin/rotations');modal(adminRotationsMarkup(data));startAdminRotationLive(data);$('newAdminRotation').onclick=()=>editAdminRotation(data,null);for(const name of ['edit','toggle','delete'])document.querySelectorAll(`[data-rotation-${name}]`).forEach(b=>b.onclick=async()=>{const r=data.rotations.find(x=>x.id===Number(b.dataset['rotation'+name[0].toUpperCase()+name.slice(1)]));if(!r)return;if(name==='edit'){editAdminRotation(data,r);return}b.disabled=true;try{if(name==='delete'){if(!confirm('删除轮换计划？请先暂停。将停止两台 VPS 的自动换 IP 动作与重试，取消未下发的重启任务，保留当前 DNS。已发出的动作无法撤回。'))return;await api(`admin/servers/${r.primary_server_id}/rotation`,'DELETE');}else await api(`admin/servers/${r.primary_server_id}/rotation`,'PUT',{other_server_id:r.other_server_id,binding_id:r.binding_id,interval_s:r.interval_s,lead_s:r.lead_s,offline_after_s:r.offline_after_s,connection_threshold:r.connection_threshold,enabled:!r.enabled});await loadAdminRotations();}catch(e){$('adminRotationMessage').textContent=e.message;}finally{b.disabled=false;}});}catch(e){notice(e.message);}
}
function editAdminRotation(data,r){
 modal(`<h2>${r?'配置':'创建'}后台双 VPS 轮换</h2><button type="button" id="backAdminRotations">← 返回轮换列表</button><p>先在后台“检测点配置”为两台 VPS 开启定时探测，并分别选择重启或指定正确的换 IP API；在下方直接读取域名和 A 记录，也可选用已有绑定。保存轮换不会立即换 IP，预检不会改 DNS。</p><form id="adminRotationForm">${rotationModeFields(r,data.servers,data.bindings,r?.primary_server_id||data.servers[0]?.id)}<h3>1. 选择机器与解析</h3><label>主 VPS<select name="primary_server_id" ${r?'disabled':''} required>${data.servers.map(s=>`<option value="${s.id}" ${r?.primary_server_id===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>轮换 VPS<select name="other_server_id" ${r?'disabled':''} required><option value="">选择另一台 VPS</option>${data.servers.map(s=>`<option value="${s.id}" ${r?.other_server_id===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>${!r?`<fieldset><legend>直接从 DNS 服务商读取域名</legend><label>后台 DNS API 连接<select name="dns_connection_id"><option value="">选择阿里云 / Cloudflare 连接</option>${(data.dns_connections||[]).map(c=>`<option value="${c.id}">${esc(c.name)} · ${c.kind==='alidns'?'阿里云':'Cloudflare'}</option>`).join('')}</select></label><label>选择或输入主域名<input name="rotation_domain" list="rotationDnsDomains" placeholder="example.com" autocomplete="off"></label><datalist id="rotationDnsDomains"></datalist><button type="button" id="loadRotationDnsRecords">读取 A 记录</button><label>具体记录与线路<select name="rotation_record"><option value="">请读取 DNS 记录</option></select></label><button type="button" id="chooseRotationDnsRecord" disabled>选用此记录（不修改 DNS）</button><p id="rotationDnsPickerStatus" role="status">不需要提前绑定。选择后会核对主 VPS 公网 IP 和记录线路，仅保存面板绑定。</p></fieldset>`:''}<label>已选 DNS A 记录<select name="binding_id" ${r?'disabled':''} required></select></label><button type="button" id="checkAdminRotation">检查配置（不换 IP、不修改 DNS）</button><div id="adminRotationChecks"></div><h3>2. 时间与恢复条件</h3><label>轮换周期（分钟）<input name="interval_minutes" type="number" min="1" max="10080" value="${r?r.interval_s/60:120}" required></label><label>提前发布 DNS（分钟）<input name="lead_minutes" type="number" min="0" max="10079" value="${r?(r.lead_s||0)/60:2}" required></label><label>无心跳切换阈值（秒）<input name="offline_after_s" type="number" min="10" max="120" value="${r?.offline_after_s||15}" required></label><label>正常轮换旧机 TCP 连接阈值（严格低于）<input name="connection_threshold" type="number" min="1" max="10000" value="${r?.connection_threshold||80}" required></label><p>当前 IP 全节点确认不通后优先切回健康备用机，故障机跳过连接数等待换 IP；离线触发切换，但不凭无心跳反复换 IP。</p><label><input name="enabled" type="checkbox" ${!r||r.enabled?'checked':''}> 开启轮换</label><button type="submit" class="primary">保存轮换</button><p id="adminRotationError" role="status"></p></form>`);
 const form=$('adminRotationForm');bindFailoverChoices(form,r?.primary_server_id);$('backAdminRotations').onclick=()=>loadAdminRotations();const bindings=()=>{form.binding_id.innerHTML='<option value="">选择主 VPS 的 DNS 记录</option>'+data.bindings.filter(b=>b.server_id===Number(form.primary_server_id.value)&&(r?b.id===r.binding_id:b.credential_owner==null)).map(b=>`<option value="${b.id}" ${r?.binding_id===b.id?'selected':''}>${esc(b.rr==='@'?b.domain:b.rr+'.'+b.domain)} · ${esc(b.line)} · ${esc(b.expected_ip)}</option>`).join('')};bindings();form.primary_server_id.onchange=bindings;bindAdminRotationDNSPicker(data,form,bindings);
 form.interval_minutes.onchange=()=>{if(Number(form.lead_minutes.value)>=Number(form.interval_minutes.value))form.lead_minutes.value=Math.max(0,Number(form.interval_minutes.value)-1);};
 $('checkAdminRotation').onclick=async()=>{const button=$('checkAdminRotation');button.disabled=true;try{const result=await api(`admin/servers/${form.primary_server_id.value}/rotation/readiness`,'POST',{...rotationModePayload(form),other_server_id:Number(form.other_server_id.value),binding_id:Number(form.binding_id.value)});$('adminRotationChecks').innerHTML=result.checks.map(x=>`<p>${x.ok?'✓':'✗'} ${esc(x.name)}：${esc(x.message)}</p>`).join('');if(!r&&result.recommended_lead_s)form.lead_minutes.value=Math.min(Math.ceil(result.recommended_lead_s/60),Math.max(0,Number(form.interval_minutes.value)-1));}catch(e){$('adminRotationChecks').textContent=e.message;}finally{button.disabled=false;}};
 form.onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await api(`admin/servers/${form.primary_server_id.value}/rotation`,'PUT',{...rotationModePayload(form),other_server_id:Number(form.other_server_id.value),binding_id:Number(form.binding_id.value),interval_s:Number(form.interval_minutes.value)*60,lead_s:Number(form.lead_minutes.value)*60,offline_after_s:Number(form.offline_after_s.value),connection_threshold:Number(form.connection_threshold.value),enabled:form.enabled.checked});await loadAdminRotations();notice('轮换设置已保存');}catch(err){$('adminRotationError').textContent=err.message;}finally{b.disabled=false;}};
}

function adminRotationRecordOptions(records,domain){
 return '<option value="">选择具体 A 记录 / 运营商线路</option>'+records.map((r,i)=>`<option value="${i}">${esc(r.RR==='@'?domain:r.RR+'.'+domain)} · ${esc(dnsLineLabel(r.Line))} · ${esc(r.Value)} · #${esc(r.RecordId)}</option>`).join('');
}
function bindAdminRotationDNSPicker(data,form,refreshBindings){
 const select=form.dns_connection_id;if(!select)return;
 const domain=form.rotation_domain,records=form.rotation_record,load=$('loadRotationDnsRecords'),choose=$('chooseRotationDnsRecord'),status=$('rotationDnsPickerStatus');let rows=[],version=0;
 const reset=()=>{rows=[];records.innerHTML='<option value="">请读取 DNS 记录</option>';choose.disabled=true;form.binding_id.value='';};
 const read=async()=>{const cid=Number(select.value),host=domain.value.trim(),v=++version;reset();if(!cid||!host){status.textContent='请选择 DNS API 连接和主域名。';return}load.disabled=true;status.textContent='正在读取域名下的 A 记录…';try{const result=await api(`admin/rotation-dns/${cid}/records`,'POST',{domain:host});if(v!==version)return;domain.value=result.domain;rows=result.records||[];records.innerHTML=adminRotationRecordOptions(rows,result.domain);status.textContent=`读取到 ${rows.length} 条启用的 A 记录。${result.truncated?'列表已截断，请在供应商核对未显示记录。':''}同域名不同运营商线路分别选择；读取不会修改 DNS。`;}catch(e){if(v===version)status.textContent=e.message;}finally{if(v===version)load.disabled=false;}};
 select.onchange=async()=>{const cid=Number(select.value),v=++version;reset();domain.value='';$('rotationDnsDomains').innerHTML='';status.textContent='正在读取域名列表…';load.disabled=false;if(!cid){status.textContent='请选择后台 DNS API 连接。';return}try{const result=await api(`admin/rotation-dns/${cid}/domains`);if(v!==version)return;$('rotationDnsDomains').innerHTML=result.domains.map(x=>`<option value="${esc(x)}"></option>`).join('');status.textContent=result.truncated?'域名列表已截断，可直接输入已授权的主域名。':'请选择或输入主域名，再读取 A 记录。';if(result.domains.length===1){domain.value=result.domains[0];await read();}}catch(e){if(v===version)status.textContent='无法列出域名：'+e.message+'。如果凭据仅授权指定域名，可手动输入主域名再读取记录。';}};
 domain.oninput=()=>{version++;reset();load.disabled=false;};load.onclick=read;records.onchange=()=>{choose.disabled=!rows[Number(records.value)]||records.value==='';};
 choose.onclick=async()=>{const r=records.value===''?null:rows[Number(records.value)];if(!r)return;const v=version,sid=Number(form.primary_server_id.value);choose.disabled=true;try{const result=await api(`admin/servers/${sid}/rotation/dns-binding`,'POST',{connection_id:Number(select.value),domain:domain.value.trim(),record_id:String(r.RecordId)});if(v!==version||sid!==Number(form.primary_server_id.value))return;data.bindings=data.bindings.filter(b=>b.id!==result.binding.id).concat([result.binding]);refreshBindings();form.binding_id.value=String(result.binding.id);status.textContent=result.message;}catch(e){status.textContent=e.message;}finally{choose.disabled=false;}};
}
